449	  it('stops asking for tools once maxToolRounds is spent', async () => {
450	    const alwaysTools = Array.from({length: 10}, () => [TOOL_CALL, STOP_FOR_TOOL]);
451	    const orchestrator = createChatOrchestrator(
452	      scriptedProvider(alwaysTools),
453	      promptBuilder,
454	      registryReturning({result: 'again'}),
455	      {maxToolRounds: 2}
456	    );
457	
458	    const chunks = await chunksFrom(orchestrator.processMessageStream(createSession('ask')));
459	
460	    expect(chunks.filter(c => c.type === 'tool_use')).toHaveLength(3);
461	  });
462	
463	  it('forwards the client messages a tool returned as one tool_result chunk', async () => {
464	    const forwarded: OutgoingMessage = {type: 'entry_commit', index: 7};
465	    const orchestrator = createChatOrchestrator(
466	      scriptedProvider([[TOOL_CALL, STOP_FOR_TOOL], [STOP_DONE]]),
467	      promptBuilder,
468	      registryReturning({result: 'r', clientMessages: [forwarded]})
469	    );
470	
471	    const chunks = await chunksFrom(orchestrator.processMessageStream(createSession('ask')));
472	
473	    expect(chunks).toContainEqual({type: 'tool_result', clientMessages: [forwarded]});
